@WebMvcTest(CuentaController.class)
class CuentaControllerTest {

    @Autowired
    private MockMvc mockMvc;

    @MockBean
    private CuentaService service;

    @Test
    void shouldReturnCuenta_whenExists() throws Exception {
        when(service.findById(1L)).thenReturn(new CuentaDto(1L, "Ana", "ana@test.com", 2500, true));

        mockMvc.perform(get("/api/cuentas/1")
                .accept(MediaType.APPLICATION_JSON))
            .andExpect(status().isOk())
            .andExpect(jsonPath("$.id").value(1))
            .andExpect(jsonPath("$.nombre").value("Ana"))
            .andExpect(jsonPath("$.saldo").value(2500));
    }

    @Test
    void shouldReturn404_whenNotFound() throws Exception {
        when(service.findById(99L)).thenThrow(new ResourceNotFoundException("Cuenta", 99L));

        mockMvc.perform(get("/api/cuentas/99"))
            .andExpect(status().isNotFound());
    }

    @Test
    void shouldReturn400_whenInvalidInput() throws Exception {
        String body = "{\"nombre\": \"\", \"email\": \"invalido\"}";

        mockMvc.perform(post("/api/cuentas")
                .contentType(MediaType.APPLICATION_JSON)
                .content(body))
            .andExpect(status().isBadRequest());
    }
}

@SpringBootTest(webEnvironment = WebEnvironment.RANDOM_PORT)
class CuentaIntegrationTest {

    @Autowired
    private TestRestTemplate restTemplate;

    @Test
    void shouldCreateAndRetrieveCuenta() {
        // Crear
        CrearCuentaRequest req = new CrearCuentaRequest("Ana", "ana@test.com");
        ResponseEntity<CuentaDto> createResponse = restTemplate.postForEntity(
            "/api/cuentas", req, CuentaDto.class);
        assertThat(createResponse.getStatusCode()).isEqualTo(HttpStatus.CREATED);
        Long id = createResponse.getBody().id();

        // Obtener
        ResponseEntity<CuentaDto> getResponse = restTemplate.getForEntity(
            "/api/cuentas/" + id, CuentaDto.class);
        assertThat(getResponse.getStatusCode()).isEqualTo(HttpStatus.OK);
        assertThat(getResponse.getBody().nombre()).isEqualTo("Ana");

        // Eliminar
        restTemplate.delete("/api/cuentas/" + id);
        ResponseEntity<CuentaDto> deletedResponse = restTemplate.getForEntity(
            "/api/cuentas/" + id, CuentaDto.class);
        assertThat(deletedResponse.getStatusCode()).isEqualTo(HttpStatus.NOT_FOUND);
    }
}

